public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the given table (index)
    Mappings current = getMappingFromIndex(tableName);
    if (current == null) {
        return new Mappings();
    }

    // Get the property maps from both mappings
    Map<String, Object> currentProps = current.getProperties();
    Map<String, Object> inputProps = mappings.getProperties();

    // Prepare a new mapping to hold the differences
    Mappings diff = new Mappings();

    // Iterate over current properties and add those not present in the input mapping
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();

        // Skip the _source configuration to avoid update conflicts
        if ("_source".equals(field)) {
            continue;
        }

        if (!inputProps.containsKey(field)) {
            diff.put(field, entry.getValue());
        }
    }

    return diff;
}

