        osVersion != null && osVersion.startsWith("5.0")) {
        // Windows 2000: create lf5 in the Documents and Settings directory
        String userHome = System.getProperty("user.home");
        File userHomeFile = new File(userHome);
        File parent = userHomeFile.getParentFile();
        if (parent != null) {
            dirPath = new File(parent, "lf5").getAbsolutePath();
        } else {
