static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(c) && i + 1 < end) {
            char next = str.charAt(i + 1);
            if (Character.isLowSurrogate(next)) {
                codePoint = Character.toCodePoint(c, next);
                i++; // skip low surrogate
            } else {
                // Unmatched high surrogate, treat as a single code unit
                codePoint = c;
            }
        } else {
            codePoint = c;
        }

        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

