private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    int start = strLen - suffixLen;
    if (ignoreCase) {
        return str.regionMatches(true, start, suffix, 0, suffixLen);
    } else {
        return str.startsWith(suffix, start);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return new ArrayList<>();
    }
    // If the path is absolute, ignore the leading '/'
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // If the path is now empty, return an empty list
    if (rawPath.isEmpty()) {
        return new ArrayList<>();
    }
    // Split on '/' and keep empty segments
    String[] parts = rawPath.split("/", -1);
    List<PathSegmentImpl> segments = new ArrayList<>(parts.length);
    for (String part : parts) {
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (Exception e) {
                // If decoding fails, keep the raw part
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

