@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Null values are returned as null
    if (value == null) {
        return null;
    }

    // If the value is already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }

    // If the value is a String, it must be exactly one character long
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new Exception("Cannot convert String to Character: length must be 1");
        }
    }

    // If the value is a Number, cast its integer value to a char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }

    // For any other type, attempt to use its string representation
    String str = value.toString();
    if (str.length() == 1) {
        return Character.valueOf(str.charAt(0));
    }

    // If none of the above worked, throw an exception
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

