public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the escaped backslash
            } else {
                switch (next) {
                    case 'b':
                        sb.append('\b');
                        i++;
                        break;
                    case 'f':
                        sb.append('\f');
                        i++;
                        break;
                    case 'n':
                        sb.append('\n');
                        i++;
                        break;
                    case 'r':
                        sb.append('\r');
                        i++;
                        break;
                    case 't':
                        sb.append('\t');
                        i++;
                        break;
                    case '\'':
                        sb.append('\'');
                        i++;
                        break;
                    case '\"':
                        sb.append('\"');
                        i++;
                        break;
                    case 'u':
                        if (i + 5 < str.length()) {
                            String hex = str.substring(i + 2, i + 6);
                            try {
                                int code = Integer.parseInt(hex, 16);
                                sb.append((char) code);
                                i += 5; // skip \uXXXX
                            } catch (NumberFormatException e) {
                                sb.append('\\').append('u');
                                i++;
                            }
                        } else {
                            sb.append('\\').append('u');
                            i++;
                        }
                        break;
                    default:
                        if (next >= '0' && next <= '7') {
                            int j = i + 1;
                            int end = j;
                            int count = 0;
                            while (end < str.length() && count < 3
                                    && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                                end++;
                                count++;
                            }
                            String oct = str.substring(i + 1, end);
                            try {
                                int code = Integer.parseInt(oct, 8);
                                sb.append((char) code);
                                i = end - 1;
                            } catch (NumberFormatException e) {
                                sb.append('\\').append(next);
                                i++;
                            }
                        } else {
                            sb.append('\\').append(next);
                            i++;
                        }
                        break;
                }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

