protected int removeUnusedNodes(){
    if(this.children == null) return 0;
    int removed = 0;
    java.util.Iterator<Category> it = this.children.iterator();
    while(it.hasNext()){
        Category child = it.next();
        if(!child.isActive()){
            int count = 0;
            java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
            stack.push(child);
            while(!stack.isEmpty()){
                Category n = stack.pop();
                count++;
                if(n.children != null){
                    for(Category c : n.children){
                        stack.push(c);
                    }
                }
            }
            removed += count;
            it.remove();
        } else {
            removed += child.removeUnusedNodes();
        }
    }
    return removed;
}

