final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // classFileBuffer is assumed to be a byte array field of the containing class
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("Constant pool index must be > 0");
    }
    int offset = 8; // skip magic (4), minor_version (2), major_version (2)
    // read constant_pool_count (u2)
    int constantPoolCount = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    for (int i = 1; i < constantPoolCount; i++) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        if (i == constantPoolEntryIndex) {
            if (tag != 1) {
                throw new IllegalArgumentException("Requested constant pool entry is not a CONSTANT_Utf8");
            }
            int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
            offset += 2;
            if (length > charBuffer.length) {
                throw new IllegalArgumentException("Provided charBuffer is too small for the UTF8 string");
            }
            byte[] bytes = new byte[length];
            System.arraycopy(classFileBuffer, offset, bytes, 0, length);
            String str;
            try {
                str = new String(bytes, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
            str.getChars(0, str.length(), charBuffer, 0);
            return str;
        } else {
            // skip over this entry
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                    offset += 2 + len;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                case 15: // CONSTANT_MethodHandle
                case 16: // CONSTANT_MethodType
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    i++; // these take up two entries in the constant pool
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                case 19: // CONSTANT_Module
                case 20: // CONSTANT_Package
                    offset += 2;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
            }
        }
    }
    throw new IllegalArgumentException("Constant pool index out of bounds");
}

