private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null) {
        return null;
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the start node is the stop node, return immediately
    if (stop != null && start.equals(stop)) {
        return circ;
    }
    // If stop is null, just search until the predicate is satisfied
    if (stop == null) {
        while (!predicate.test(circ.getNode())) {
            circ.next();
        }
        return circ;
    }
    // Traverse until we hit the stop node or find a node satisfying the predicate
    while (!circ.getNode().equals(stop) && !predicate.test(circ.getNode())) {
        circ.next();
    }
    return circ;
}

