        byte[] newBuf = new byte[newCap];
        System.arraycopy(this.buffer, 0, newBuf, 0, this.length);
        this.buffer = newBuf;
    }
    if(byteArrayValue == null){
        for(int i = 0; i < byteLength; i++){
            this.buffer[this.length + i] = 0;
        }
    }else{
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.length, byteLength);
    }
    this.length = newLen;
    return this;
}

