protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }
    // Build adjacency map
    java.util.Map<V, java.util.List<E>> adjacency = new java.util.HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(e);
    }
    if (adjacency.isEmpty()) {
        return null;
    }
    boolean directed = graph.getType().isDirected();
    V start = adjacency.keySet().iterator().next();
    V current = start;
    E previousEdge = null;
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    java.util.Set<V> visited = new java.util.HashSet<>();
    while (true) {
        vertexList.add(current);
        visited.add(current);
        java.util.List<E> edges = adjacency.get(current);
        if (edges == null || edges.isEmpty()) {
            break;
        }
        E nextEdge = null;
        for (E e : edges) {
            if (e.equals(previousEdge)) {
                continue;
            }
            if (directed) {
                if (!graph.getEdgeSource(e).equals(current)) {
                    continue;
                }
            }
            nextEdge = e;
            break;
        }
        if (nextEdge == null) {
            break;
        }
        edgeList.add(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        if (next.equals(start) && edgeList.size() == tour.size()) {
            vertexList.add(next);
            break;
        }
        current = next;
        previousEdge = nextEdge;
    }
    if (edgeList.isEmpty()) {
        return null;
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, start, start, vertexList, edgeList, weight);
}

