private String unescapeId(String input){
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'v':
                    sb.append('\u000B');
                    i++;
                    break;
                case '0':
                    sb.append('\0');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'x':
                    int hexStart = i + 2;
                    int hexEnd = hexStart;
                    while (hexEnd < len && hexEnd - hexStart < 2) {
                        char hc = input.charAt(hexEnd);
                        if ((hc >= '0' && hc <= '9') ||
                            (hc >= 'a' && hc <= 'f') ||
                            (hc >= 'A' && hc <= 'F')) {
                            hexEnd++;
                        } else {
                            break;
                        }
                    }
                    if (hexEnd > hexStart) {
                        String hex = input.substring(hexStart, hexEnd);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i = hexEnd - 1;
                    } else {
                        sb.append('x');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int octStart = i + 1;
                        int octEnd = octStart;
                        while (octEnd < len && octEnd - octStart < 3) {
                            char oc = input.charAt(octEnd);
                            if (oc >= '0' && oc <= '7') {
                                octEnd++;
                            } else {
                                break;
                            }
                        }
                        String oct = input.substring(octStart, octEnd);
                        sb.append((char) Integer.parseInt(oct, 8));
                        i = octEnd - 1;
                    } else {
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

