public void putAllWriteable(BeanMap map){
    Object sourceBean = map.getBean();
    if (sourceBean == null) {
        return;
    }
    java.beans.BeanInfo beanInfo;
    try {
        beanInfo = java.beans.Introspector.getBeanInfo(sourceBean.getClass());
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
    for (java.beans.PropertyDescriptor pd : beanInfo.getPropertyDescriptors()) {
        String name = pd.getName();
        if ("class".equals(name)) {
            continue;
        }
        if (pd.getReadMethod() != null && pd.getWriteMethod() != null) {
            Object value = map.getProperty(name);
            try {
                this.setProperty(name, value);
            } catch (Exception ignored) {
                // ignore if target property is not writable
            }
        }
    }
}

