public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    // Select the specified row
    table.setRowSelectionInterval(row, row);
    // Scroll the table to make the row visible
    Rectangle rect = table.getCellRect(row, 0, true);
    if (rect != null) {
        table.scrollRectToVisible(rect);
    }
    // Delay repaint to allow the table to paint the newly selected row
    SwingUtilities.invokeLater(() -> {
        table.repaint();
        pane.repaint();
    });
}

public ByteVector putInt(final int intValue){
    if (size + 4 > capacity) {
        int newCap = Math.max(capacity * 2, size + 4);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, size);
        buf = newBuf;
        capacity = newCap;
    }
    buf[size++] = (byte)(intValue >>> 24);
    buf[size++] = (byte)(intValue >>> 16);
    buf[size++] = (byte)(intValue >>> 8);
    buf[size++] = (byte)intValue;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (a == b) {
        return true;
    }
    if (a == null || b == null) {
        return false;
    }
    if (count <= 0) {
        return true;
    }
    if (count > a.length || count > b.length) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
