private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Convert to array for indexed access
    Object[] arr = vertices.toArray();
    for (int i = 0; i < arr.length; i++) {
        V v1 = (V) arr[i];
        for (int j = i + 1; j < arr.length; j++) {
            V v2 = (V) arr[j];
            // For an undirected graph, a single edge suffices
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    int n = (keys == null) ? 0 : keys.size();
    List<Integer> lowerBounds = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        lowerBounds.add(-1);
    }
    if (n == 0) {
        return lowerBounds;
    }
    Integer[] indices = new Integer[n];
    for (int i = 0; i < n; i++) {
        indices[i] = i;
    }
    Arrays.sort(indices, new Comparator<Integer>() {
        @SuppressWarnings("unchecked")
        public int compare(Integer a, Integer b) {
            K ka = keys.get(a);
            K kb = keys.get(b);
            if (ka == null && kb == null) {
                return 0;
            }
            if (ka == null) {
                return -1;
            }
            if (kb == null) {
                return 1;
            }
            return ((Comparable<? super K>) ka).compareTo(kb);
        }
    });
    for (int i = 0; i < n; i++) {
        int idx = indices[i];
        if (i == 0) {
            lowerBounds.set(idx, -1);
        } else {
            int predIdx = indices[i - 1];
            lowerBounds.set(idx, predIdx);
        }
    }
    return lowerBounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    // If descriptor is a method descriptor, pop all argument types
    if (descriptor.charAt(0) == '('){
        int i = 1;
        while (descriptor.charAt(i) != ')'){
            // Skip over the type descriptor
            char c = descriptor.charAt(i);
            if (c == '['){
                // Array: skip all '['
                while (descriptor.charAt(i) == '['){
                    i++;
                }
                // Then skip the component type
                c = descriptor.charAt(i);
                if (c == 'L'){
                    i++; // skip 'L'
                    while (descriptor.charAt(i) != ';'){
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    // Primitive component
                    i++;
                }
            } else if (c == 'L'){
                // Object type: skip until ';'
                i++; // skip 'L'
                while (descriptor.charAt(i) != ';'){
                    i++;
                }
                i++; // skip ';'
            } else {
                // Primitive type
                i++;
            }
            // Pop one type from the output frame stack
            outputFrameStack.pop();
        }
        // Return type after ')' is ignored
    } else {
        // Single type descriptor
        if (!descriptor.equals("V")){
            outputFrameStack.pop();
        }
    }
}

