static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        return (String[]) array;
    }
    String[] result = new String[array.length - nullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

